/**
 * Recipe corpus for the on-device recommender: the core set below plus regional Indian (indian.ts)
 * and international (world.ts) recipes. The training script (scripts/train-recipe-model.ts)
 * learns ingredient embeddings and ranking weights from it, and the app ships it so the model can
 * recommend full recipes with steps when there is no network or no AI provider.
 *
 * Compact row format, expanded by `corpus()`:
 *   [title, cuisine, description, tags, difficulty, prepMin, cookMin, kcal, servings,
 *    [proteinG, carbsG, fatG], emoji, ingredients (canonical names), steps, chefTip]
 * A step may end in "@<seconds>" to attach a timer.
 */
import { DF, GF, HP, KETO, LC, NF, PALEO, REGION_OF, Row, VEG, VG } from './schema';
import { INDIAN_ROWS } from './indian';
import { WORLD_ROWS } from './world';

export interface CorpusRecipe {
  id: string;
  title: string;
  cuisine: string;
  region: string;
  description: string;
  tags: string[];
  difficulty: 'Easy' | 'Medium' | 'Hard';
  prepTimeMinutes: number;
  cookTimeMinutes: number;
  calories: number;
  servings: number;
  macros: [number, number, number];
  emoji: string;
  ingredients: string[];
  steps: { instruction: string; timerSeconds?: number }[];
  chefTip: string;
}



