const ROWS: Row[] = [...CORE_ROWS, ...INDIAN_ROWS, ...WORLD_ROWS];

export const corpus = (): CorpusRecipe[] =>
  ROWS.map(([title, cuisine, description, tags, difficulty, prep, cook, kcal, servings, macros, emoji, ingredients, steps, chefTip]) => ({
    id: 'local-' + title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    title,
    cuisine,
    region: REGION_OF[cuisine] || 'Fusion',
    description,
    tags,
    difficulty,
    prepTimeMinutes: prep,
    cookTimeMinutes: cook,
    calories: kcal,
    servings,
    macros,
    emoji,
    ingredients,
    steps: steps.map((s) => {
      const m = /@(\d+)$/.exec(s);
      return m ? { instruction: s.slice(0, m.index).trim(), timerSeconds: Number(m[1]) } : { instruction: s };
    }),
    chefTip,
  }));
